mapper.select:
SELECT po.id, po.po_no, po.supplier_id, s.supplier_name, po.order_date, po.expected_delivery_date, po.total_amount, po.total_tax, po.total_amount_with_tax, po.status, po.reject_reason, po.payment_terms, po.remarks, po.created_at, po.updated_at FROM purchase_orders po LEFT JOIN suppliers s ON po.supplier_id = s.id
po.deleted = 0
AND s.supplier_name LIKE CONCAT('%', #{supplierName}, '%')
AND po.status = #{status}
AND po.order_date >= #{startDate}
AND po.order_date <= #{endDate}
ORDER BY po.id DESC
